import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
/**
 * "Presented by" a sponsor, linking to its page. `compact` for cards: plain
 * text there, since the whole card is already a link.
 */
export default class SponsorBanner extends Component {
  view() {
    const {
      sponsor,
      compact
    } = this.attrs;
    const inner = [m("span", {
      className: "SponsorBanner-label"
    }, app.translator.trans('ernestdefoe-giveaways.forum.sponsors.presented_by')), sponsor.logoUrl && m("img", {
      className: "SponsorBanner-logo",
      src: sponsor.logoUrl,
      alt: "",
      loading: "lazy",
      decoding: "async"
    }), m("span", {
      className: "SponsorBanner-name"
    }, sponsor.name)];
    return compact ? m("span", {
      className: "SponsorBanner SponsorBanner--compact"
    }, inner) : m(Link, {
      className: "SponsorBanner",
      href: app.route('giveaways.sponsor', {
        slug: sponsor.slug
      })
    }, inner);
  }
}
flarum.reg.add('ernestdefoe-giveaways', 'forum/sponsors/SponsorBanner', SponsorBanner);